#include "goal1_velocity_endpoint.hpp"
#include <iostream>
#include <iomanip>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;namespace vm=cs::velocity_momentum;namespace ve=cs::velocity_endpoint;
Real FirstError(const cs::Jet&a,const cs::Jet&b){Real err=std::abs(a.f-b.f)/std::max({Real(1),std::abs(a.f),std::abs(b.f)});for(int d=0;d<3;++d)err=std::max(err,std::abs(a.d[d]-b.d[d])/std::max({Real(1),std::abs(a.d[d]),std::abs(b.d[d])}));return err;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0,index;Real eps,x[3];try{while(std::cin>>index>>eps>>x[0]>>x[1]>>x[2]){
 h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){Real a;if(!(std::cin>>a))throw std::runtime_error("short endpoint fixture");return a;});h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);auto ref=ve::OuterReference(p,x);auto state=ve::NativeSecondValues(u);auto connection=cs::endpoint_point::OuterConnection(x);auto parts=vm::MomentumParts(state,ref,connection);auto W=ve::Assemble(parts,ref.omega);auto F=vm::SourceParts(state,ref,connection);std::array<cs::Jet,3>Q;Real source_compatibility=0;bool source_valid=F.valid;for(int i=0;i<3;++i){auto q=ve::DivideSecond(F.pole[7+i],ref.omega);Q[i]=q.first;source_valid=source_valid&&q.valid;source_compatibility=std::max({source_compatibility,q.pole,q.tangent,q.second});}
 std::array<cs::Jet,10>truth;for(int d=0;d<3;++d){std::array<cs::Jet,10>g;if(!vm::GradientDeviation(state,ref.state,d,g))throw std::runtime_error("invalid endpoint chart gradient");for(int n=0;n<10;++n)truth[n]-=state.beta.value[d]*g[n];}Real Werror=0;for(int n=0;n<10;++n)Werror=std::max(Werror,FirstError(W.value[n],truth[n]));auto inverse=state;bool inverse_valid=vm::ReconstructWithQuotient(inverse,ref,F,truth,Q);Real value_error=0,first_error=0;auto compare=[&](const cs::Jet&a,const cs::Jet&b){value_error=std::max(value_error,std::abs(a.f-b.f)/std::max({Real(1),std::abs(a.f),std::abs(b.f)}));first_error=std::max(first_error,FirstError(a,b));};compare(inverse.trace.value,state.trace.value);compare(inverse.theta.value,state.theta.value);for(int i=0;i<3;++i){compare(inverse.lambda.value[i],state.lambda.value[i]);for(int j=i;j<3;++j)compare(inverse.a.k[i][j],state.a.k[i][j]);}
 auto bad=F.pole[7];bad.f+=.001;bool nonzero_rejected=!ve::DivideSecond(bad,ref.omega).valid;bad=F.pole[7];Real t[3]={1,0,0},nn=0;for(int d=0;d<3;++d)nn+=ref.omega.d[d]*ref.omega.d[d];if(std::abs(ref.omega.d[0])>1.5){t[0]=0;t[1]=1;}Real dot=0;for(int d=0;d<3;++d)dot+=t[d]*ref.omega.d[d];for(int d=0;d<3;++d)t[d]-=dot*ref.omega.d[d]/nn;for(int i=0;i<3;++i)for(int j=0;j<3;++j)bad.h[i][j]+=.001*t[i]*t[j];bool second_rejected=!ve::DivideSecond(bad,ref.omega).valid;
 std::cout<<"{\"case\":"<<index<<",\"epsilon\":"<<eps<<",\"valid\":"<<(W.valid&&source_valid&&inverse_valid?"true":"false")<<",\"velocity_value_first_scaled\":"<<Werror<<",\"native_value_inverse_scaled\":"<<value_error<<",\"native_first_inverse_scaled\":"<<first_error<<",\"velocity_pole_compatibility_absolute\":"<<W.compatibility<<",\"source_beta_pole_compatibility_absolute\":"<<source_compatibility<<",\"nonzero_pole_rejected\":"<<(nonzero_rejected?"true":"false")<<",\"second_tangential_incompatibility_rejected\":"<<(second_rejected?"true":"false")<<",\"W_value_first\":[";for(int n=0;n<10;++n){if(n)std::cout<<",";std::cout<<"["<<W.value[n].f;for(int d=0;d<3;++d)std::cout<<","<<W.value[n].d[d];std::cout<<"]";}std::cout<<"]}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;status=2;}Kokkos::finalize();return status;}
